pub async fn get_hits(session: &::scylla::client::session::Session, id: ::uuid::Uuid) -> ::std::result::Result<::std::option::Option<GetHitsRow>, CqlcError> {
    let prepared = session.prepare(GET_HITS_CQL).await.map_err(|e| CqlcError::new("GetHits", CqlcErrorKind::Prepare, e))?;
    get_hits_with(session, &prepared, id).await
}

/// All queries, prepared once. Cheap to share behind an `Arc`.
///
/// Prefer this over the free functions when queries run repeatedly: each free
/// function prepares its statement on every call.
#[derive(Debug)]
pub struct Queries {
    session: ::std::sync::Arc<::scylla::client::session::Session>,
    get_all: ::scylla::statement::prepared::PreparedStatement,
    insert_scalars: ::scylla::statement::prepared::PreparedStatement,
    insert_rest: ::scylla::statement::prepared::PreparedStatement,
    list_in_range: ::scylla::statement::prepared::PreparedStatement,
    list_by_ids: ::scylla::statement::prepared::PreparedStatement,
    set_type: ::scylla::statement::prepared::PreparedStatement,
    delete_range: ::scylla::statement::prepared::PreparedStatement,
    get_hits: ::scylla::statement::prepared::PreparedStatement,
}

impl Queries {
    /// Prepares every statement on `session`.
    pub async fn new(session: ::std::sync::Arc<::scylla::client::session::Session>) -> ::std::result::Result<Self, CqlcError> {
        let get_all = session.prepare(GET_ALL_CQL).await.map_err(|e| CqlcError::new("GetAll", CqlcErrorKind::Prepare, e))?;
        let insert_scalars = session.prepare(INSERT_SCALARS_CQL).await.map_err(|e| CqlcError::new("InsertScalars", CqlcErrorKind::Prepare, e))?;
        let insert_rest = session.prepare(INSERT_REST_CQL).await.map_err(|e| CqlcError::new("InsertRest", CqlcErrorKind::Prepare, e))?;
        let list_in_range = session.prepare(LIST_IN_RANGE_CQL).await.map_err(|e| CqlcError::new("ListInRange", CqlcErrorKind::Prepare, e))?;
        let list_by_ids = session.prepare(LIST_BY_IDS_CQL).await.map_err(|e| CqlcError::new("ListByIds", CqlcErrorKind::Prepare, e))?;
        let set_type = session.prepare(SET_TYPE_CQL).await.map_err(|e| CqlcError::new("SetType", CqlcErrorKind::Prepare, e))?;
        let delete_range = session.prepare(DELETE_RANGE_CQL).await.map_err(|e| CqlcError::new("DeleteRange", CqlcErrorKind::Prepare, e))?;
        let get_hits = session.prepare(GET_HITS_CQL).await.map_err(|e| CqlcError::new("GetHits", CqlcErrorKind::Prepare, e))?;
        Ok(Queries { session, get_all, insert_scalars, insert_rest, list_in_range, list_by_ids, set_type, delete_range, get_hits })
    }

    /// The session the statements were prepared on.
    pub fn session(&self) -> &::scylla::client::session::Session {
        &self.session
    }

    pub async fn get_all(&self, params: GetAllParams) -> ::std::result::Result<::std::option::Option<GetAllRow>, CqlcError> {
        get_all_with(&self.session, &self.get_all, params).await
    }

    pub async fn insert_scalars(&self, params: InsertScalarsParams) -> ::std::result::Result<(), CqlcError> {
        insert_scalars_with(&self.session, &self.insert_scalars, params).await
    }

    pub async fn insert_rest(&self, params: InsertRestParams) -> ::std::result::Result<(), CqlcError> {
        insert_rest_with(&self.session, &self.insert_rest, params).await
    }

    pub async fn list_in_range(&self, params: ListInRangeParams) -> ::std::result::Result<::std::vec::Vec<ListInRangeRow>, CqlcError> {
        list_in_range_with(&self.session, &self.list_in_range, params).await
    }

    pub async fn stream_list_in_range(&self, params: ListInRangeParams) -> ::std::result::Result<::futures::stream::BoxStream<'static, ::std::result::Result<ListInRangeRow, CqlcError>>, CqlcError> {
        stream_list_in_range_with(&self.session, &self.list_in_range, params).await
    }

    pub async fn list_by_ids(&self, id: ::std::vec::Vec<::uuid::Uuid>) -> ::std::result::Result<::std::vec::Vec<ListByIdsRow>, CqlcError> {
        list_by_ids_with(&self.session, &self.list_by_ids, id).await
    }

    pub async fn stream_list_by_ids(&self, id: ::std::vec::Vec<::uuid::Uuid>) -> ::std::result::Result<::futures::stream::BoxStream<'static, ::std::result::Result<ListByIdsRow, CqlcError>>, CqlcError> {
        stream_list_by_ids_with(&self.session, &self.list_by_ids, id).await
    }

    pub async fn set_type(&self, params: SetTypeParams) -> ::std::result::Result<(), CqlcError> {
        set_type_with(&self.session, &self.set_type, params).await
    }

    pub async fn delete_range(&self, params: DeleteRangeParams) -> ::std::result::Result<(), CqlcError> {
        delete_range_with(&self.session, &self.delete_range, params).await
    }

    pub async fn get_hits(&self, id: ::uuid::Uuid) -> ::std::result::Result<::std::option::Option<GetHitsRow>, CqlcError> {
        get_hits_with(&self.session, &self.get_hits, id).await
    }
}

